+/** UC-002: directory rendering, lazy requests, empty data, and read failures. */
+class UC002ViewVeterinariansTest extends PetClinicTestBase {
+
+    @Autowired
+    private DSLContext dsl;
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = {"BR-002", "BR-003"})
+    void navigationOpensAnonymousDirectoryWithNamesAndOrderedSpecialties() {
+        navigate(WelcomeView.class);
+        SideNavItem link = assertDoesNotThrow(() -> find(SideNavItem.class)
+                .withPropertyValue(SideNavItem::getLabel, "Veterinarians").single(),
+                "Expected veterinarian navigation item");
+        UI.getCurrent().navigate(link.getPath());
+
+        assertEquals("vets", UI.getCurrent().getInternals().getActiveViewLocation().getPath());
+        Grid<Vet> grid = directory();
+        assertEquals(6, test(grid).size());
+        assertEquals(List.of("First Name", "Last Name", "Specialties"),
+                List.of(test(grid).getHeaderCell(0), test(grid).getHeaderCell(1), test(grid).getHeaderCell(2)));
+        assertEquals("James", test(grid).getCellText(0, 0));
+        assertEquals("Carter", test(grid).getCellText(0, 1));
+        assertEquals("none", test(grid).getCellText(0, 2));
+        assertEquals("Linda", test(grid).getCellText(1, 0));
+        assertEquals("Douglas", test(grid).getCellText(1, 1));
+        assertEquals("dentistry, surgery", test(grid).getCellText(1, 2));
+        assertEquals("radiology", test(grid).getCellText(3, 2));
+        assertEquals(6, dsl.fetchCount(VETS), "Browsing must leave veterinarian data unchanged");
+        assertEquals(5, dsl.fetchCount(VET_SPECIALTIES), "Browsing must leave specialties unchanged");
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void callbackFetchesOnlyRequestedChunksWithStableBoundaries() {
+        var insert = dsl.insertInto(VETS, VETS.FIRST_NAME, VETS.LAST_NAME);
+        for (int i = 0; i < 120; i++) {
+            insert = insert.values("Additional", "Vet%03d".formatted(i));
+        }
+        insert.execute();
+        navigate(VeterinariansView.class);
+        var provider = directory().getDataProvider();
+        assertInstanceOf(CallbackDataProvider.class, provider);
+        assertEquals(126, provider.size(new Query<>()));
+
+        var first = provider.fetch(page(0, 2)).toList();
+        var next = provider.fetch(page(2, 2)).toList();
+        assertEquals(List.of("Carter", "Douglas"), first.stream().map(Vet::lastName).toList());
+        assertEquals(List.of("Jenkins", "Leary"), next.stream().map(Vet::lastName).toList());
+        assertEquals(first, provider.fetch(page(0, 2)).toList(), "Repeated requests must be stable");
+        assertEquals("Vet119", provider.fetch(page(125, 2)).toList().getFirst().lastName());
+        assertTrue(provider.fetch(page(126, 2)).toList().isEmpty());
+    }
+
+    @Test
+    @UseCase(id = "UC-002", scenario = "A1: No Veterinarians Registered")
