+        dsl.deleteFrom(VETS).execute();
+        navigate(VeterinariansView.class);
+
+        Grid<Vet> grid = directory();
+        assertEquals(0, test(grid).size());
+        assertTrue(grid.getDataProvider().fetch(page(0, 20)).toList().isEmpty());
