+        var provider = directory().getDataProvider();
+        dsl.dropTable(VET_SPECIALTIES).execute();
+
+        assertTrue(provider.fetch(page(0, 20)).toList().isEmpty());
+        assertErrorView();
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void countFailureReplacesDirectoryWithApplicationErrorView() {
+        navigate(VeterinariansView.class);
+        var provider = directory().getDataProvider();
+        dsl.dropTable(VET_SPECIALTIES).execute();
+        dsl.dropTable(VETS).execute();
+
+        assertEquals(0, provider.size(new Query<>()));
+        assertErrorView();
+    }
+
+    private void assertErrorView() {
+        assertDoesNotThrow(() -> find(ApplicationErrorView.class).single(),
+                "Expected the shared application error view after a database failure");
+        assertFalse(find(Paragraph.class).all().isEmpty(), "Expected an error message");
+        assertTrue(find(Grid.class).all().isEmpty(), "Failed directory must no longer be displayed");
+        assertDoesNotThrow(() -> find(SideNavItem.class)
+                .withPropertyValue(SideNavItem::getLabel, "Home").single(),
+                "Expected navigation to remain available after failure");
+    }
+
+    @SuppressWarnings("unchecked")
+    private Grid<Vet> directory() {
+        return assertDoesNotThrow(() -> find(Grid.class).single(), "Expected veterinarian grid");
+    }
+
+    private <F> Query<Vet, F> page(int offset, int limit) {
+        return new Query<>(offset, limit, List.of(), null, null);
+    }
